// The Unicode character database (round 84) - see include/NyUniData.hpp.
// The tables are generated by tools/gen_unicodedata.py from python3's own
// database; the algorithms are CPython 3.11's (Modules/unicodedata.c).
#include "NyUniData.hpp"
#include "NyUniDataTables.hpp"
#include <algorithm>
#include <cstdio>
#include <mutex>
#include <unordered_map>

namespace nyucd {
namespace {

const char* const kCategoryNames[] = {"Cn", "Lu", "Ll", "Lt", "Mn", "Mc", "Me", "Nd", "Nl", "No", "Zs",
                                      "Zl", "Zp", "Cc", "Cf", "Cs", "Co", "Cn", "Lm", "Lo", "Pc", "Pd",
                                      "Ps", "Pe", "Pi", "Pf", "Po", "Sm", "Sc", "Sk", "So"};
const char* const kBidiNames[] = {"", "L", "LRE", "LRO", "R", "AL", "RLE", "RLO", "PDF", "EN", "ES", "ET",
                                  "AN", "CS", "NSM", "BN", "B", "S", "WS", "ON", "LRI", "RLI", "FSI", "PDI"};
const char* const kEawNames[] = {"F", "H", "W", "Na", "A", "N"};

const uint32_t SBase = 0xAC00, LBase = 0x1100, VBase = 0x1161, TBase = 0x11A7;
const uint32_t LCount = 19, VCount = 21, TCount = 28, NCount = VCount * TCount, SCount = LCount * NCount;

template <typename T1, typename T2, typename T3>
uint32_t trie3(const T1* t1, const T2* t2, const T3* t3, int lo, int mid, uint32_t cp) {
    uint32_t i = t1[cp >> (lo + mid)];
    i = t2[(i << mid) + ((cp >> lo) & ((1u << mid) - 1))];
    return t3[(i << lo) + (cp & ((1u << lo) - 1))];
}

uint32_t decomp_index(uint32_t cp) {
    if (cp >= 0x110000) return 0;
    return trie3(data::kDecIdx1, data::kDecIdx2, data::kDecIdx3, data::kDecLo, data::kDecMid, cp);
}

uint32_t old_norm(uint32_t cp) {
    for (auto& p : data::kOldNorm) if (p[0] == cp) return p[1];
    return 0;
}

// the canonical composite of (a, b), 0 when there is none
uint32_t compose(uint32_t a, uint32_t b) {
    uint64_t key = ((uint64_t)a << 42) | ((uint64_t)b << 21);
    const uint64_t* end = data::kComp + sizeof(data::kComp) / sizeof(data::kComp[0]);
    const uint64_t* it = std::lower_bound(data::kComp, end, key);
    if (it != end && (*it >> 21) == (key >> 21)) return (uint32_t)(*it & 0x1FFFFF);
    return 0;
}
// can a start a canonical composition (CPython's nfc_first)?
bool comp_first(uint32_t a) {
    uint64_t key = (uint64_t)a << 42;
    const uint64_t* end = data::kComp + sizeof(data::kComp) / sizeof(data::kComp[0]);
    const uint64_t* it = std::lower_bound(data::kComp, end, key);
    return it != end && (*it >> 42) == a;
}
// can b end one (nfc_last)? A table built once.
bool comp_last(uint32_t b) {
    static std::vector<uint32_t>* lasts = [] {
        auto* v = new std::vector<uint32_t>();
        for (uint64_t k : data::kComp) v->push_back((uint32_t)((k >> 21) & 0x1FFFFF));
        std::sort(v->begin(), v->end());
        v->erase(std::unique(v->begin(), v->end()), v->end());
        return v;
    }();
    return std::binary_search(lasts->begin(), lasts->end(), b);
}

void get_decomp_record(uint32_t code, bool old, uint32_t& index, int& prefix, int& count) {
    if (code >= 0x110000 || (old && !assigned_3_2_0(code))) index = 0;
    else index = decomp_index(code);
    count = (int)(data::kDecompData[index] >> 8);
    prefix = (int)(data::kDecompData[index] & 255);
    index++;
}

void u8put(uint32_t cp, std::string& out) {
    if (cp < 0x80) out += (char)cp;
    else if (cp < 0x800) { out += (char)(0xC0 | (cp >> 6)); out += (char)(0x80 | (cp & 0x3F)); }
    else if (cp < 0x10000) {
        out += (char)(0xE0 | (cp >> 12)); out += (char)(0x80 | ((cp >> 6) & 0x3F)); out += (char)(0x80 | (cp & 0x3F));
    } else {
        out += (char)(0xF0 | (cp >> 18)); out += (char)(0x80 | ((cp >> 12) & 0x3F));
        out += (char)(0x80 | ((cp >> 6) & 0x3F)); out += (char)(0x80 | (cp & 0x3F));
    }
}

}  // namespace

double to_numeric(uint32_t c) {
    if (c < 0x80) return c >= '0' && c <= '9' ? (double)(c - '0') : -1.0;
    if (!(rec(c).flags & NUMERIC)) return -1.0;
    const uint32_t* end = data::kNumCp + sizeof(data::kNumCp) / sizeof(data::kNumCp[0]);
    const uint32_t* it = std::lower_bound(data::kNumCp, end, c);
    if (it == end || *it != c) return -1.0;
    return data::kNumVal[data::kNumIdx[it - data::kNumCp]];
}

const char* category(uint32_t c) { return kCategoryNames[rec(c).cat]; }
const char* bidirectional(uint32_t c) { return kBidiNames[rec(c).bidi]; }
const char* east_asian_width(uint32_t c) { return kEawNames[rec(c).eawm >> 1]; }

std::string decomposition(uint32_t c) {
    uint32_t index = decomp_index(c);
    int count = (int)(data::kDecompData[index] >> 8);
    std::string r = data::kDecompPrefix[data::kDecompData[index] & 255];
    char buf[16];
    while (count-- > 0) {
        if (!r.empty()) r += ' ';
        std::snprintf(buf, sizeof buf, "%04X", (unsigned)data::kDecompData[++index]);
        r += buf;
    }
    return r;
}

// ── 3.2.0 ─────────────────────────────────────────────────────────────────
Old old_record(uint32_t c) {
    if (c >= 0x110000) return Old{0xFF, 0xFF, 0xFF, 0xFF, 0xFF};
    uint32_t i = trie3(data::kOldIdx1, data::kOldIdx2, data::kOldIdx3, data::kOldLo, data::kOldMid, c);
    const uint8_t* r = data::kOld[i];
    return Old{r[0], r[1], r[2], r[3], r[4]};
}
bool assigned_3_2_0(uint32_t c) { return old_record(c).category != 0; }
const char* category_3_2_0(uint32_t c) {
    const Old o = old_record(c);
    return kCategoryNames[o.category != 0xFF ? o.category : rec(c).cat];
}
const char* bidirectional_3_2_0(uint32_t c) {
    const Old o = old_record(c);
    if (o.category == 0) return kBidiNames[0];
    return kBidiNames[o.bidir != 0xFF ? o.bidir : rec(c).bidi];
}
const char* east_asian_width_3_2_0(uint32_t c) {
    const Old o = old_record(c);
    if (o.category == 0) return kEawNames[0];   // (CPython's: index 0)
    return kEawNames[o.eaw != 0xFF ? o.eaw : rec(c).eawm >> 1];
}
int combining_3_2_0(uint32_t c) { return old_record(c).category == 0 ? 0 : rec(c).ccc; }
int mirrored_3_2_0(uint32_t c) {
    const Old o = old_record(c);
    if (o.category == 0) return 0;
    return o.mirrored != 0xFF ? o.mirrored : (rec(c).eawm & 1);
}
int decimal_3_2_0(uint32_t c) {
    const Old o = old_record(c);
    if (o.category == 0) return -1;
    if (o.decimal != 0xFF) return o.decimal;
    return to_decimal(c);
}
double numeric_3_2_0(uint32_t c) {
    // (CPython's unicodedata.UCD.numeric reads the decimal change record)
    const Old o = old_record(c);
    if (o.category == 0) return -1.0;
    if (o.decimal != 0xFF) return o.decimal;
    return to_numeric(c);
}
std::string decomposition_3_2_0(uint32_t c) { return old_record(c).category == 0 ? std::string() : decomposition(c); }

// ── normalization ─────────────────────────────────────────────────────────
bool form_of(const std::string& name, Form& f) {
    if (name == "NFC") f = NFC;
    else if (name == "NFKC") f = NFKC;
    else if (name == "NFD") f = NFD;
    else if (name == "NFKD") f = NFKD;
    else return false;
    return true;
}

static std::vector<uint32_t> nfd_nfkd(const std::vector<uint32_t>& in, bool k, bool old) {
    std::vector<uint32_t> out;
    out.reserve(in.size() + 10);
    std::vector<uint32_t> stack;
    for (uint32_t ch : in) {
        stack.push_back(ch);
        while (!stack.empty()) {
            uint32_t code = stack.back();
            stack.pop_back();
            if (code >= SBase && code < SBase + SCount) {
                uint32_t SIndex = code - SBase;
                out.push_back(LBase + SIndex / NCount);
                out.push_back(VBase + (SIndex % NCount) / TCount);
                uint32_t T = TBase + SIndex % TCount;
                if (T != TBase) out.push_back(T);
                continue;
            }
            if (old) {
                uint32_t v = old_norm(code);
                if (v) { stack.push_back(v); continue; }
            }
            uint32_t index;
            int prefix, count;
            get_decomp_record(code, old, index, prefix, count);
            if (!count || (prefix && !k)) { out.push_back(code); continue; }
            while (count) stack.push_back(data::kDecompData[index + (uint32_t)(--count)]);
        }
    }
    // each run of combining characters in canonical order (a stable sort)
    size_t i = 0, o = out.size();
    while (i < o) {
        int prev = rec(out[i]).ccc;
        if (prev == 0) { i++; continue; }
        size_t start = i++;
        bool needs = false;
        while (i < o) {
            int cur = rec(out[i]).ccc;
            if (cur == 0) break;
            if (prev > cur) needs = true;
            prev = cur;
            i++;
        }
        if (!needs) continue;
        std::stable_sort(out.begin() + (long)start, out.begin() + (long)i,
                         [](uint32_t a, uint32_t b) { return rec(a).ccc < rec(b).ccc; });
    }
    return out;
}

static std::vector<uint32_t> nfc_nfkc(const std::vector<uint32_t>& in, bool k, bool old) {
    std::vector<uint32_t> data = nfd_nfkd(in, k, old);
    size_t len = data.size(), i = 0;
    std::vector<uint32_t> output;
    output.reserve(len);
    std::vector<size_t> skipped;
    while (i < len) {
        bool skip = false;
        for (size_t s = 0; s < skipped.size(); s++)
            if (skipped[s] == i) { skipped[s] = skipped.back(); skipped.pop_back(); skip = true; break; }
        if (skip) { i++; continue; }
        uint32_t code = data[i];
        // Hangul composition (the data is decomposed: no <LV, T> pairs)
        if (code >= LBase && code < LBase + LCount && i + 1 < len && data[i + 1] >= VBase && data[i + 1] < VBase + VCount) {
            uint32_t LIndex = code - LBase, VIndex = data[i + 1] - VBase;
            code = SBase + (LIndex * VCount + VIndex) * TCount;
            i += 2;
            if (i < len && TBase < data[i] && data[i] < TBase + TCount) { code += data[i] - TBase; i++; }
            output.push_back(code);
            continue;
        }
        if (!comp_first(code)) { output.push_back(code); i++; continue; }
        size_t i1 = i + 1;
        int comb = 0;
        output.push_back(data[i]);
        size_t o = output.size() - 1;
        while (i1 < len) {
            uint32_t code1 = data[i1];
            int comb1 = rec(code1).ccc;
            if (comb) {
                if (comb1 == 0) break;
                if (comb >= comb1) { i1++; continue; }   // blocked
            }
            uint32_t composite = comp_last(code1) ? compose(output[o], code1) : 0;
            if (composite == 0) {
                if (comb1 == 0) break;
                comb = comb1;
                i1++;
                continue;
            }
            output[o] = composite;
            skipped.push_back(i1);
            i1++;
            if (!comp_first(output[o])) break;
        }
        i++;
    }
    return output;
}

int quickcheck(Form f, const std::vector<uint32_t>& s, bool yes_only) {
    bool nfc = f == NFC || f == NFKC, k = f == NFKC || f == NFKD;
    int shift = (nfc ? 4 : 0) + (k ? 2 : 0);
    bool ascii = true;
    for (uint32_t c : s) if (c >= 0x80) { ascii = false; break; }
    if (ascii) return 0;
    int result = 0, prev = 0;
    for (uint32_t c : s) {
        const Rec& r = rec(c);
        if (r.ccc && prev > r.ccc) return 2;
        prev = r.ccc;
        int q = (r.qc >> shift) & 3;
        if (yes_only) { if (q) return 1; }
        else if (q == 2) return 2;
        else if (q == 1) result = 1;
    }
    return result;
}

std::vector<uint32_t> normalize(Form f, const std::vector<uint32_t>& s, bool old) {
    if (s.empty()) return s;
    if (!old && quickcheck(f, s, true) == 0) return s;
    bool k = f == NFKC || f == NFKD;
    if (f == NFC || f == NFKC) return nfc_nfkc(s, k, old);
    return nfd_nfkd(s, k, old);
}

bool is_normalized(Form f, const std::vector<uint32_t>& s, bool old) {
    if (s.empty()) return true;
    int m = old ? 1 : quickcheck(f, s, false);
    if (m == 1) {
        bool k = f == NFKC || f == NFKD;
        return ((f == NFC || f == NFKC) ? nfc_nfkc(s, k, old) : nfd_nfkd(s, k, old)) == s;
    }
    return m == 0;
}

std::string normalize_utf8(Form f, const std::string& s, bool old) {
    bool ascii = true;
    for (unsigned char ch : s) if (ch >= 0x80) { ascii = false; break; }
    if (ascii && !old) return s;
    std::vector<uint32_t> cps;
    cps.reserve(s.size());
    for (size_t i = 0; i < s.size();) {
        unsigned char ch = (unsigned char)s[i];
        uint32_t cp;
        size_t n;
        if (ch < 0x80) { cp = ch; n = 1; }
        else if ((ch & 0xE0) == 0xC0) { cp = ch & 0x1Fu; n = 2; }
        else if ((ch & 0xF0) == 0xE0) { cp = ch & 0x0Fu; n = 3; }
        else { cp = ch & 0x07u; n = 4; }
        if (i + n > s.size()) n = 1;
        for (size_t k = 1; k < n; k++) cp = (cp << 6) | ((unsigned char)s[i + k] & 0x3Fu);
        cps.push_back(cp);
        i += n;
    }
    std::vector<uint32_t> r = normalize(f, cps, old);
    if (r == cps) return s;
    std::string out;
    out.reserve(s.size() + 8);
    for (uint32_t c : r) u8put(c, out);
    return out;
}

std::vector<uint32_t> stream_safe(const std::vector<uint32_t>& s) {
    // UAX #15 section 13: no more than 30 non-starters in a row, counted
    // over each character's NFKD (as the standard's algorithm does)
    std::vector<uint32_t> out;
    out.reserve(s.size());
    int run = 0;
    for (uint32_t c : s) {
        std::vector<uint32_t> d = nfd_nfkd(std::vector<uint32_t>{c}, true, false);
        size_t lead = 0;
        while (lead < d.size() && rec(d[lead]).ccc != 0) lead++;
        size_t trail = 0;
        while (trail < d.size() && rec(d[d.size() - 1 - trail]).ccc != 0) trail++;
        if (lead == d.size()) {
            if (run + (int)lead > 30) { out.push_back(0x34F); run = 0; }
            run += (int)lead;
        } else {
            if (run + (int)lead > 30) out.push_back(0x34F);
            run = (int)trail;
        }
        out.push_back(c);
    }
    return out;
}

// ── aliases and named sequences ───────────────────────────────────────────
bool alias_lookup(const std::string& upper, uint32_t& cp) {
    static std::unordered_map<std::string, uint32_t>* m = [] {
        auto* t = new std::unordered_map<std::string, uint32_t>();
        for (auto& a : data::kAliases) t->emplace(a.name, a.cp);
        return t;
    }();
    auto it = m->find(upper);
    if (it == m->end()) return false;
    cp = it->second;
    return true;
}

bool named_sequence_lookup(const std::string& upper, std::vector<uint32_t>& seq) {
    static std::unordered_map<std::string, int>* m = [] {
        auto* t = new std::unordered_map<std::string, int>();
        int n = (int)(sizeof(data::kNamedSeqs) / sizeof(data::kNamedSeqs[0]));
        for (int i = 0; i < n; i++) t->emplace(data::kNamedSeqs[i].name, i);
        return t;
    }();
    auto it = m->find(upper);
    if (it == m->end()) return false;
    const auto& e = data::kNamedSeqs[it->second];
    seq.assign(e.seq, e.seq + e.len);
    return true;
}

}  // namespace nyucd
